node --input-type=module -e "
import { executeWorkflowAsync } from './src/engine.js';
const WHEN = Date.parse('2024-01-02T03:04:05.000Z');
const workflow = {
  id: 'repro', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'f' },
    { id: 'f', type: 'form', next: 'act', schema: { fields: [
      { path: 'failure.cause.createdAt.channel', type: 'string', default: 'web' },
    ] } },
    { id: 'act', type: 'action', operation: 'op', compensation: { operation: 'undo' }, next: 'end' },
    { id: 'end', type: 'end', result: 'done' },
  ],
};
const input = { failure: new TypeError('boom', { cause: { createdAt: new Date(WHEN) } }) };
const seen = [];
const result = await executeWorkflowAsync(workflow, input, {
  op: (inp) => { seen.push(inp.failure.cause.createdAt.channel); return { ok: true }; },
