import { executeWorkflowAsync } from './src/engine.js';
const WHEN = Date.parse('2024-01-02T03:04:05.000Z');
const workflow = {
  id: 'repro', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'f' },
    { id: 'f', type: 'form', next: 'act', schema: { fields: [
      { path: 'failure.cause.createdAt.channel', type: 'string', default: 'web' },
    ] } },
    { id: 'act', type: 'action', operation: 'op', compensation: { operation: 'undo' }, next: 'boom' },
    { id: 'boom', type: 'action', operation: 'boom', next: 'end' },
    { id: 'end', type: 'end', result: 'done' },
  ],
};
const date = new Date(WHEN);
const failure = new TypeError('boom', { cause: { createdAt: date } });
const compSeen = [];
const result = await executeWorkflowAsync(workflow, { failure }, {
  op: (inp) => {
    const d = inp.failure.cause.createdAt;
    console.log('action channel:', d.channel, '| isDate:', d instanceof Date, '| time:', d.getTime());
    console.log('error message preserved:', inp.failure.message, '| error is TypeError(Error):', inp.failure instanceof Error);
    console.log('cause still non-enumerable?', Object.getOwnPropertyDescriptor(inp.failure,'cause').enumerable === false);
    console.log('copy detached from caller date?', d !== date);
    return { ok: true };
  },
  undo: (inp) => { compSeen.push(inp.failure.cause.createdAt.channel); return 'u'; },
  boom: () => { throw new Error('later boom'); },
});
console.log('status:', result.status, '| compensation saw channel:', compSeen);
"

