import { executeWorkflowAsync } from './src/engine.js';
import assert from 'node:assert/strict';
const WHEN = Date.parse('2024-01-02T03:04:05.000Z');

function wf(fields, {comp=false, retry=false}={}) {
  const act = { id: 'act', type: 'action', operation: 'op', next: 'end' };
  if (comp) { act.compensation = { operation: 'undo' }; act.next = 'boom'; }
  if (retry) act.retry = { attempts: 2, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
  return { id:'w', entry:'start', nodes: [
    { id:'start', type:'trigger', next:'f' },
    { id:'f', type:'form', next:'act', schema:{fields} },
    act,
    ...(comp ? [{id:'boom',type:'action',operation:'boom',next:'end'}] : []),
    { id:'end', type:'end', result:'done' },
  ]};
}
const fields = [
  { path: 'failure.cause.createdAt.channel', type:'string', default:'web' },
  { path: 'failure.cause.createdAt.meta.source', type:'string', default:'form' },
  { path: 'failure.cause.createdAt.meta.kind', type:'string', default:'kind-default' },
];

// Scenario A: cause is directly a Date
{
  const date = new Date(WHEN);
  await executeWorkflowAsync(wf([{path:'failure.cause.channel', type:'string', default:'web'}]),
    { failure: new Error('e', { cause: date }) },
    { op:(inp)=>{ const c=inp.failure.cause; assert.ok(c instanceof Date); assert.equal(c.getTime(),WHEN); assert.equal(c.channel,'web'); assert.notEqual(c,date); return 1; } });
  console.log('A direct-date cause: OK');
}
// Scenario B: cause -> another Error -> cause plain -> Date
{
  const date = new Date(WHEN);
  await executeWorkflowAsync(wf(fields),
    { failure: new Error('outer', { cause: new TypeError('inner', { cause: { createdAt: date } }) }) },
    { op:(inp)=>{ const d=inp.failure.cause.cause.createdAt; assert.ok(d instanceof Date); assert.equal(d.channel,'web'); assert.deepEqual(d.meta,{source:'form',kind:'kind-default'}); assert.equal(inp.failure.message,'outer'); assert.equal(inp.failure.cause.message,'inner'); assert.notEqual(d,date); return 1; } });
  console.log('B nested-error cause: OK');
}
// Scenario C: Date reachable ONLY through cause (no other path); alias within cause graph
{
  const date = new Date(WHEN);
  const inner = { createdAt: date };
  const failure = new Error('e', { cause: inner });
  inner.self = inner; // cycle in plain portion
  failure.cause.again = date; // same date via second key inside cause
  await executeWorkflowAsync(wf(fields),
    { failure },
    { op:(inp)=>{ const d=inp.failure.cause.createdAt; assert.equal(d.channel,'web'); assert.equal(inp.failure.cause.again, d, 'alias within copy'); assert.equal(inp.failure.cause.self, inp.failure.cause, 'cycle preserved'); assert.notEqual(d,date); return 1; } });
  console.log('C cause-only + alias + cycle: OK');
}
// Scenario D: same Date reachable via cause AND via plain field -> single identity in copy
{
  const date = new Date(WHEN);
  const failure = new Error('e', { cause: { createdAt: date } });
  const input = { failure, other: date };
  await executeWorkflowAsync(wf(fields), input,
    { op:(inp)=>{ assert.equal(inp.failure.cause.createdAt, inp.other, 'cross-path alias'); assert.equal(inp.other.channel,'web'); return 1; } });
  console.log('D cross-path (cause + plain) alias: OK');
}
